globalThis.HAKI_GATE_CSS = ":host {\n  all: initial;\n  --haki-bg: #040b13; --haki-surface: #091725; --haki-surface-hover: #10263a;\n  --haki-text: #edf4ff; --haki-text-muted: #9db1c9; --haki-accent: #159bff;\n  --haki-accent-secondary: #51c8ff; --haki-border: #20374e; --haki-success: #6edcc4;\n  --haki-radius-sm: 8px; --haki-radius-md: 14px; --haki-radius-lg: 22px;\n  --haki-shadow: 0 24px 90px #0008;\n  color-scheme: dark;\n}\n* { box-sizing: border-box; }\ndialog {\n  all: initial; box-sizing: border-box; position: fixed; inset: 0; margin: 0;\n  width: 100vw; height: 100dvh; max-width: none; max-height: none;\n  display: flex; flex-direction: column; align-items: center; overflow: auto;\n  background: var(--haki-bg); color: var(--haki-text);\n  font: 15px/1.5 Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\n  padding: 32px 24px; outline: none; overscroll-behavior: contain;\n  background-image: radial-gradient(ellipse at 50% -30%, #063c7560, transparent 65%), linear-gradient(#12365a22 1px, transparent 1px), linear-gradient(90deg, #12365a22 1px, transparent 1px);\n  background-size: auto, 100px 100px, 100px 100px;\n  opacity: 1; transition: opacity 300ms ease;\n}\ndialog::backdrop { background: #040b13; }\ndialog.leaving { opacity: 0; }\n.ritual { width: min(100%, 520px); margin: auto; padding: 20px 0; text-align: center; }\n.wordmark { display: flex; align-items: baseline; justify-content: center; gap: .02em; letter-spacing: -.035em; font-size: 24px; line-height: 1; font-weight: 700; }\n.mark { display: inline-block; flex: none; width: .8064em; height: .72em; background: #39baff; clip-path: polygon(10.71% 0, 31.44% 0, 27.14% 40.18%, 74.97% 40.18%, 79.27% 0, 100% 0, 89.29% 100%, 68.56% 100%, 72.86% 59.82%, 25.03% 59.82%, 20.73% 100%, 0 100%); }\n.eyebrow { font-size: 10px; color: var(--haki-accent-secondary); letter-spacing: .28em; margin: 36px 0 12px; font-weight: 600; }\nh1 { font-size: clamp(27px, 5vw, 36px); letter-spacing: .06em; font-weight: 500; margin: 0 0 14px; line-height: 1.2; }\n.intro { color: var(--haki-text-muted); margin: 0 0 28px; font-size: 15px; }\n.rules { display: grid; gap: 10px; text-align: left; }\nbutton { font: inherit; cursor: pointer; }\n.rule {\n  width: 100%; display: flex; align-items: center; gap: 17px; text-align: left;\n  padding: 18px 20px; border: 1px solid var(--haki-border); border-radius: var(--haki-radius-md);\n  background: #07131fee; color: var(--haki-text); transition: border-color 160ms, background 160ms, transform 160ms;\n}\n.rule:hover { border-color: #397098; background: var(--haki-surface-hover); }\n.rule:active { transform: scale(.992); }\n.rule[aria-checked=true] { border-color: var(--haki-accent); background: #08243a; }\n.circle { flex: 0 0 26px; height: 26px; border: 1px solid #41607e; border-radius: 50%; display: grid; place-items: center; color: transparent; font-size: 15px; }\n[aria-checked=true] .circle { background: #129bff20; border-color: var(--haki-accent-secondary); color: var(--haki-accent-secondary); box-shadow: 0 0 15px #159bff25; }\n.rule-text { overflow-wrap: anywhere; }\n.progress { font-size: 10px; letter-spacing: .2em; color: var(--haki-text-muted); margin: 23px 0 12px; }\n.track { height: 2px; background: #182b3e; margin-bottom: 22px; border-radius: 2px; }\n.fill { height: 100%; width: 0; background: var(--haki-accent); transition: width 180ms; }\n.primary { width: 100%; min-height: 54px; border: 1px solid #48b8ff; border-radius: var(--haki-radius-sm); background: #119aff; color: #001322; font-size: 12px; font-weight: 750; letter-spacing: .16em; transition: background 160ms, box-shadow 160ms; }\n.primary:hover:not(:disabled) { background: #51bbff; box-shadow: 0 0 24px #159bff30; }\n.primary:disabled { cursor: not-allowed; color: #73889f; border-color: #20374e; background: #102030; }\nbutton:focus-visible { outline: 3px solid var(--haki-accent-secondary); outline-offset: 4px; }\n.footer { font-size: 11px; letter-spacing: .05em; color: #8197af; margin: 24px 0 0; }\n.success-check { width: 72px; height: 72px; margin: 45px auto 28px; border: 1px solid var(--haki-accent); border-radius: 50%; color: var(--haki-accent-secondary); display: grid; place-items: center; font-size: 30px; box-shadow: 0 0 45px #159bff20; }\n.secondary { margin-top: 14px; width: 100%; padding: 14px; color: var(--haki-text-muted); border: 1px solid var(--haki-border); border-radius: 8px; background: var(--haki-surface); }\n.error { color: #ffc2b8; font-size: 13px; margin: 16px 0; }\n@media (max-height: 650px) { dialog { padding: 16px 20px; } .eyebrow { margin-top: 22px; } .rule { padding: 14px 16px; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; animation: none !important; } }\n";
